const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two locations
  const loc1 = ee.Geometry.Point([136.025799, 33.710618]);
  const loc2 = ee.Geometry.Point([136.367495, 33.884848]);

  // Define date
  const date = '2018-09-15';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // Load MODIS Terra Daily Surface Reflectance
  let collection = ee.ImageCollection('MODIS/061/MOD09GA')
    .filterDate(startDate, endDate)
    .filterBounds(loc1.union(loc2));

  const collectionSize = collection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No MODIS Terra images found for September 15, 2018');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the first (and likely only) image
  const image = collection.first();

  // Use red band (sur_refl_b01) as turbidity proxy - higher values indicate more turbidity
  const redBand = image.select('sur_refl_b01');

  // Create a simple cloud mask using state_1km QA band
  const qa = image.select('state_1km');
  const cloudMask = qa.bitwiseAnd(3).eq(0); // Clear sky
  const maskedRed = redBand.updateMask(cloudMask);

  // Calculate turbidity (red band reflectance) at location 1
  const turb1Result = maskedRed.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: loc1,
    scale: 500,
    maxPixels: 1e9
  });

  const turb1 = turb1Result.get('sur_refl_b01').getInfo();

  // Calculate turbidity at location 2
  const turb2Result = maskedRed.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: loc2,
    scale: 500,
    maxPixels: 1e9
  });

  const turb2 = turb2Result.get('sur_refl_b01').getInfo();

  console.log(`Location 1 (33.710618, 136.025799) turbidity: ${turb1}`);
  console.log(`Location 2 (33.884848, 136.367495) turbidity: ${turb2}`);

  // Check for invalid results
  if (turb1 === null || turb2 === null) {
    console.log('Calculation failed - null values returned');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(turb1) || isNaN(turb2)) {
    console.log('Calculation failed - NaN values');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare turbidity values
  if (turb1 > turb2) {
    console.log('Location 1 has more turbidity than Location 2');
    console.log('<answer>A</answer>');
  } else {
    console.log('Location 1 does not have more turbidity than Location 2');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
